import{j as t,a as d}from"./motion-DL2UxknI.js";import{L as h}from"./LegalLayout-UnBM2fXE.js";import{a as n,u as y}from"./index-BEmxaOVh.js";import{C as m,S as b,L as f}from"./Prose-BdLWEkZn.js";import{S as c}from"./site-CU5vBIrk.js";function u(e,i){return e.split(/(\*\*[^*]+\*\*|\{[a-z]+\})/g).filter(Boolean).map((o,r)=>{const a=`${i}-${r}`;if(o.startsWith("**")&&o.endsWith("**"))return t.jsx("strong",{children:o.slice(2,-2)},a);switch(o){case"{email}":return t.jsx("a",{href:`mailto:${c.supportEmail}`,children:c.supportEmail},a);case"{whatsapp}":return t.jsx("a",{href:c.whatsapp,children:"WhatsApp"},a);case"{privacy}":return t.jsx(n,{to:"/privacy-policy",children:l(o)},a);case"{security}":return t.jsx(n,{to:"/security",children:l(o)},a);case"{contact}":return t.jsx(n,{to:"/contact",children:l(o)},a);case"{refund}":return t.jsx(n,{to:"/refund-policy",children:l(o)},a);case"{cookies}":return t.jsx(n,{to:"/cookie-policy",children:l(o)},a);default:return t.jsx(d.Fragment,{children:o},a)}})}let p={};function g(e){p=e}function l(e){return p[e]??e}function w(e,i){return"p"in e?t.jsx("p",{children:u(e.p,`p${i}`)},i):"sub"in e?t.jsx(b,{children:u(e.sub,`s${i}`)},i):"list"in e?t.jsx(f,{items:e.list.map((s,o)=>t.jsx(d.Fragment,{children:u(s,`l${i}-${o}`)},o))},i):null}function k({page:e}){return t.jsx(t.Fragment,{children:e.clauses.map((i,s)=>t.jsx(m,{n:s+1,title:i.title,children:i.blocks.map(w)},s))})}const v={cookies:{eyebrow:"Legal",title:"Cookie Policy",intro:"This policy explains what cookies MudirOS uses, what they do, and how you control them.",updated:!0,clauses:[{title:"What cookies are",blocks:[{p:"Cookies are small text files a website stores on your device. They let a site remember your actions and preferences over time. We also use similar technologies like local storage, and we refer to them all as “cookies” here."}]},{title:"How we use cookies",blocks:[{p:"We group the cookies we use into three categories:"},{list:["**Strictly necessary** — required for the site and app to function, such as keeping you signed in and keeping your session secure. These cannot be switched off.","**Analytics** — help us understand how the site is used so we can improve it, in aggregate and without identifying you personally. These load only with your consent where required.","**Preferences** — remember choices like your language, so your experience stays consistent."]},{p:"We do **not** use advertising cookies, and we do not sell data collected through cookies."}]},{title:"Third-party cookies",blocks:[{p:"Some cookies are set by trusted providers who help us run the Service — for example, our payment processor during checkout, or our analytics provider. These providers act on our behalf and are bound by contracts that protect your data."}]},{title:"Managing cookies",blocks:[{list:["Most browsers let you view, block, or delete cookies in their settings.","You can refuse non-essential cookies where we ask for consent.","Blocking strictly necessary cookies may stop parts of the Service from working."]},{p:"For guidance on managing cookies, check your browser’s help pages — the steps differ between Chrome, Safari, Firefox, and Edge."}]},{title:"Changes to this policy",blocks:[{p:"As we add or change features, the cookies we use may change too. We will update this page and the date above when that happens."}]},{title:"Contact",blocks:[{p:"Questions about cookies? Email {email}. See also our {privacy}."}]}]},privacy:{eyebrow:"Legal",title:"Privacy Policy",intro:"This policy explains what information MudirOS collects, why we collect it, and the choices you have. We keep it in plain language on purpose.",updated:!0,clauses:[{title:"Who we are",blocks:[{p:"MudirOS provides the AI Business Manager for SMEs in Saudi Arabia and the GCC. In this policy, “MudirOS,” “we,” “us,” and “our” refer to the MudirOS team. “You” refers to anyone who visits our website, requests a trial, or uses the service."}]},{title:"Information we collect",blocks:[{sub:"Information you give us"},{list:["**Trial and account details** — your name, company name, business email, optional phone number, and company size when you request a free trial or create an account.","**Business data you enter** — the sales, inventory, customer, invoice, and financial records you or your team add while using MudirOS.","**Support communications** — messages you send us by email, WhatsApp, or in-product chat."]},{sub:"Information we collect automatically"},{list:["**Usage data** — pages visited, features used, and actions taken, so we can improve the product and diagnose problems.","**Device and log data** — IP address, browser type, device type, and timestamps, collected through standard server logs.","**Cookies** — see our {cookies} for the specific cookies we use."]}]},{title:"How we use your information",blocks:[{list:["Provide, operate, and maintain the service and your workspace.","Set up and activate your 30-day free trial and any paid subscription.","Process payments and send billing notices, receipts, and renewal reminders.","Respond to your questions and provide customer support.","Send service messages about changes, security, and your account.","Improve features, reliability, and performance through aggregated analytics.","Detect, prevent, and address fraud, abuse, and security issues.","Meet legal, tax, and regulatory obligations."]},{p:"We do **not** sell your personal information, and we do not use the business data inside your workspace to train external AI models."}]},{title:"Legal bases for processing",blocks:[{p:"Where applicable, we process your information on these bases:"},{list:["**Contract** — to deliver the service you signed up for.","**Legitimate interests** — to secure, support, and improve the service.","**Consent** — for optional cookies and marketing, which you can withdraw.","**Legal obligation** — to comply with tax, accounting, and other laws."]}]},{title:"How we share information",blocks:[{p:"We share information only in these limited cases:"},{list:["**Service providers** — trusted vendors who host our infrastructure, process payments, or send email on our behalf, under contracts that require them to protect your data.","**Legal requirements** — when required by law, regulation, or valid legal process.","**Business transfers** — if MudirOS is involved in a merger, acquisition, or sale of assets, with notice to you.","**With your direction** — when you ask us to connect a third-party tool or share data with someone."]}]},{title:"Data retention",blocks:[{p:"We keep your information for as long as your account is active. If you close your account or your trial ends without conversion, we retain your data for a limited period so you can reactivate, then delete or anonymize it, except where we must keep records to meet legal, tax, or accounting obligations. You can request earlier deletion at any time."}]},{title:"Security",blocks:[{p:"We protect your data with encryption in transit and at rest, access controls, and continuous monitoring. See our {security} for details. No system is perfectly secure, but we work hard to keep your business data safe and to notify you promptly if a breach ever affects you."}]},{title:"Your rights and choices",blocks:[{list:["Access the personal information we hold about you.","Correct information that is inaccurate or incomplete.","Request deletion of your personal information.","Export your business data in a portable format.","Object to or restrict certain processing.","Withdraw consent for optional cookies or marketing at any time."]},{p:"To exercise any of these, email {email}. We respond within a reasonable timeframe and may need to verify your identity first."}]},{title:"International transfers",blocks:[{p:"Your data may be processed on servers located outside the Kingdom of Saudi Arabia. When we transfer data across borders, we use appropriate safeguards so it remains protected to the standard described in this policy."}]},{title:"Children",blocks:[{p:"MudirOS is a business tool and is not directed to anyone under 18. We do not knowingly collect information from children."}]},{title:"Changes to this policy",blocks:[{p:"We may update this policy as the product and the law evolve. When we make material changes, we will update the date above and, where appropriate, notify you by email or in the product."}]},{title:"Contact us",blocks:[{p:"Questions about privacy? Email {email} or reach us through our {contact}."}]}]},refund:{eyebrow:"Legal",title:"Refund Policy",intro:"We want MudirOS to be an easy decision. Here is exactly how trials, billing, and refunds work — no surprises.",updated:!0,clauses:[{title:"Try before you pay",blocks:[{p:"Every plan starts with a **30-day free trial**, with no credit card required. The trial is designed so you can fully evaluate MudirOS before spending anything. Because of this, most questions about “getting your money back” never come up — you only pay once you have decided the Service is right for you."}]},{title:"Monthly subscriptions",blocks:[{list:["Paid plans are billed monthly in advance.","Your subscription renews automatically each month until you cancel.","We email a receipt for every payment."]}]},{title:"Cancelling",blocks:[{p:"You can cancel anytime from your account settings. When you cancel:"},{list:["Your plan stays active until the end of the current billing period.","You are not charged again after that period ends.","You keep the ability to export your data before your access ends."]},{p:"Because access continues to the end of the period you already paid for, we do not provide partial refunds for the unused days of a monthly cycle."}]},{title:"When we do issue refunds",blocks:[{p:"We will refund a payment in cases such as:"},{list:["**Duplicate or accidental charges** — for example, being billed twice for the same period.","**Billing errors on our side** — if we charged the wrong amount, we make it right.","**A charge immediately after your trial that you did not intend** — if you contact us promptly, we will work with you in good faith.","**Extended service failure** — if a problem on our side prevents you from using the Service for a prolonged period and we cannot resolve it."]}]},{title:"How to request a refund",blocks:[{p:"Email {email} from the address on your account, or message us on {whatsapp}. Include your account email and a short note on what happened. We review every request individually and aim to respond within a few business days."}]},{title:"How refunds are paid",blocks:[{p:"Approved refunds are returned to the original payment method. The time it takes to appear depends on your bank or card provider, and is usually a few business days after we process it."}]},{title:"Taxes",blocks:[{p:"Where a refund applies to a payment that included VAT or other taxes, the refunded amount reflects the tax that was originally charged, in line with applicable regulations."}]},{title:"Questions",blocks:[{p:"If anything about billing is unclear, ask us before you are charged. Email {email} — we would rather answer a question early than sort out a charge later."}]}]},terms:{eyebrow:"Legal",title:"Terms of Service",intro:"These terms govern your use of MudirOS. By requesting a trial or using the service, you agree to them.",updated:!0,clauses:[{title:"Agreement to terms",blocks:[{p:"These Terms of Service (“Terms”) form a binding agreement between you and MudirOS regarding your use of MudirOS (the “Service”). If you use the Service on behalf of a company, you confirm you are authorized to accept these Terms for that company."}]},{title:"The service",blocks:[{p:"MudirOS is the AI Business Manager for SMEs in Saudi Arabia and the GCC. It brings sales, inventory, cashflow, customers, and reporting into one workspace, with an AI assistant that surfaces what needs your attention. We may add, change, or remove features over time to improve the Service."}]},{title:"Free trial",blocks:[{list:["The free trial lasts **30 days** from activation.","No credit card is required to start the trial.","You can use trial features to evaluate whether the Service fits your business.","At the end of the trial, you may choose a paid plan to continue, or let the trial lapse with no charge.","We may adjust trial length or availability for future sign-ups, but this will not shorten a trial already in progress."]}]},{title:"Subscriptions and billing",blocks:[{list:["Paid plans are billed **monthly** in advance, in the currency shown at checkout.","Subscriptions renew automatically each month until you cancel.","Prices are shown on our Pricing section and exclude applicable taxes (such as VAT), which are added where required.","You are responsible for keeping your billing details accurate and current.","If a payment fails, we may retry it and may suspend access until the balance is settled."]}]},{title:"Cancellations and refunds",blocks:[{p:"You can cancel your subscription at any time from your account settings; access continues until the end of the current billing period. Refunds are governed by our {refund}."}]},{title:"Your responsibilities",blocks:[{list:["Keep your login credentials confidential and secure.","Ensure everyone you invite to your workspace follows these Terms.","Provide accurate account and billing information.","Use the Service in compliance with all laws that apply to your business.","Own or have the right to use any data you upload to the Service."]}]},{title:"Acceptable use",blocks:[{p:"You agree not to:"},{list:["Break the law or infringe the rights of others while using the Service.","Attempt to access accounts, data, or systems that are not yours.","Probe, scan, or test the vulnerability of the Service without permission.","Introduce malware, or disrupt or overload our infrastructure.","Resell, sublicense, or copy the Service except as these Terms allow.","Reverse engineer the Service except where the law expressly permits it."]}]},{title:"Your data and ownership",blocks:[{p:"You own the business data you put into MudirOS. You grant us the limited rights needed to host, process, back up, and display that data so we can provide the Service. You can export your data at any time, and we handle it as described in our {privacy}."}]},{title:"Intellectual property",blocks:[{p:"The Service, including its software, design, and branding, belongs to MudirOS and is protected by intellectual-property laws. These Terms grant you a limited, non-exclusive, non-transferable right to use the Service; they do not transfer ownership of it to you."}]},{title:"Availability and support",blocks:[{p:"We work to keep the Service available and reliable, but we do not guarantee uninterrupted access. We may perform maintenance, and we may need to suspend the Service occasionally. Support is available by email and WhatsApp; response times vary by plan."}]},{title:"Third-party services",blocks:[{p:"The Service may integrate with third-party tools you choose to connect. Those tools are governed by their own terms, and we are not responsible for them."}]},{title:"Disclaimers",blocks:[{p:"The Service is provided “as is” and “as available.” To the extent permitted by law, we disclaim warranties we have not expressly stated here. MudirOS helps you manage your business, but you remain responsible for your own business decisions."}]},{title:"Limitation of liability",blocks:[{p:"To the maximum extent permitted by law, MudirOS will not be liable for indirect, incidental, or consequential damages, or for lost profits or data. Our total liability for any claim relating to the Service is limited to the amount you paid us in the twelve months before the claim arose."}]},{title:"Termination",blocks:[{p:"You may stop using the Service and cancel at any time. We may suspend or terminate access if you breach these Terms or use the Service in a way that risks harm to others or to our systems. On termination, your right to use the Service ends, and we handle your data as described in our {privacy}."}]},{title:"Governing law",blocks:[{p:"These Terms are governed by the laws of the Kingdom of Saudi Arabia. Disputes will be handled by the competent courts of the Kingdom of Saudi Arabia, unless the law requires otherwise."}]},{title:"Changes to these terms",blocks:[{p:"We may update these Terms as the Service evolves. When changes are material, we will update the date above and notify you by email or in the product. Continuing to use the Service after changes take effect means you accept the updated Terms."}]},{title:"Contact",blocks:[{p:"Questions about these Terms? Email {email} or visit our {contact}."}]}]}},S={cookies:{eyebrow:"قانوني",title:"سياسة الكوكيز",intro:"توضّح هذه السياسة ما هي الكوكيز التي يستخدمها مدير أو إس، وما تفعله، وكيف تتحكّم بها.",updated:!0,clauses:[{title:"ما هي الكوكيز",blocks:[{p:"الكوكيز ملفات نصّية صغيرة يخزّنها الموقع على جهازك. تتيح للموقع تذكّر إجراءاتك وتفضيلاتك مع الوقت. ونستخدم أيضاً تقنيات مشابهة مثل التخزين المحلّي، ونشير إليها جميعاً هنا باسم «الكوكيز»."}]},{title:"كيف نستخدم الكوكيز",blocks:[{p:"نصنّف الكوكيز التي نستخدمها إلى ثلاث فئات:"},{list:["**ضرورية تماماً** — لازمة لعمل الموقع والتطبيق، مثل إبقائك مسجّلاً للدخول وحماية جلستك. ولا يمكن إيقافها.","**تحليلية** — تساعدنا على فهم كيفية استخدام الموقع لتحسينه، بشكل إجمالي ودون تحديد هويتك. ولا تُحمّل إلا بموافقتك عند الحاجة.","**تفضيلات** — تتذكّر خياراتك مثل لغتك، لتبقى تجربتك متّسقة."]},{p:"نحن **لا** نستخدم كوكيز إعلانية، ولا نبيع البيانات المجمّعة عبر الكوكيز."}]},{title:"كوكيز الأطراف الأخرى",blocks:[{p:"بعض الكوكيز تضبطها جهات موثوقة تساعدنا في تشغيل الخدمة — مثل معالج المدفوعات أثناء الدفع، أو مزوّد التحليلات. وتعمل هذه الجهات نيابةً عنّا وتلتزم بعقود تحمي بياناتك."}]},{title:"إدارة الكوكيز",blocks:[{list:["تتيح لك معظم المتصفّحات عرض الكوكيز أو حظرها أو حذفها من الإعدادات.","يمكنك رفض الكوكيز غير الضرورية حيثما نطلب موافقتك.","قد يؤدّي حظر الكوكيز الضرورية إلى توقّف أجزاء من الخدمة عن العمل."]},{p:"للإرشادات حول إدارة الكوكيز، راجع صفحات المساعدة في متصفّحك — فالخطوات تختلف بين Chrome وSafari وFirefox وEdge."}]},{title:"تغييرات على هذه السياسة",blocks:[{p:"مع إضافة الميّزات أو تغييرها، قد تتغيّر الكوكيز التي نستخدمها أيضاً. وسنحدّث هذه الصفحة والتاريخ أعلاه عند حدوث ذلك."}]},{title:"تواصل معنا",blocks:[{p:"أسئلة حول الكوكيز؟ راسلنا على {email}. وراجع أيضاً {privacy}."}]}]},privacy:{eyebrow:"قانوني",title:"سياسة الخصوصية",intro:"توضّح هذه السياسة المعلومات التي يجمعها مدير أو إس، ولماذا نجمعها، والخيارات المتاحة لك. ونحرص على كتابتها بلغة بسيطة عن قصد.",updated:!0,clauses:[{title:"من نحن",blocks:[{p:"يقدّم مدير أو إس مدير الأعمال الذكي للشركات الصغيرة والمتوسطة في السعودية والخليج. في هذه السياسة، تشير كلمات «مدير أو إس» و«نحن» و«لنا» إلى فريق مدير أو إس. وتشير «أنت» إلى كل من يزور موقعنا أو يطلب تجربة أو يستخدم الخدمة."}]},{title:"المعلومات التي نجمعها",blocks:[{sub:"معلومات تقدّمها لنا"},{list:["**بيانات التجربة والحساب** — اسمك، واسم شركتك، وبريدك الإلكتروني للعمل، ورقم هاتفك (اختياري)، وحجم شركتك عند طلب تجربة مجانية أو إنشاء حساب.","**بيانات العمل التي تُدخلها** — سجلّات المبيعات والمخزون والعملاء والفواتير والمالية التي تضيفها أنت أو فريقك أثناء استخدام مدير أو إس.","**مراسلات الدعم** — الرسائل التي ترسلها إلينا عبر البريد أو واتساب أو المحادثة داخل المنتج."]},{sub:"معلومات نجمعها تلقائياً"},{list:["**بيانات الاستخدام** — الصفحات المزارة والميّزات المستخدمة والإجراءات المتّخذة، لتحسين المنتج وتشخيص المشاكل.","**بيانات الجهاز والسجلّات** — عنوان IP، ونوع المتصفّح، ونوع الجهاز، والأوقات، تُجمع عبر سجلّات الخادم المعتادة.","**الكوكيز** — راجع {cookies} للاطّلاع على الكوكيز المحدّدة التي نستخدمها."]}]},{title:"كيف نستخدم معلوماتك",blocks:[{list:["تقديم الخدمة ومساحة عملك وتشغيلها وصيانتها.","إعداد وتفعيل تجربتك المجانية ٣٠ يوماً وأي اشتراك مدفوع.","معالجة المدفوعات وإرسال إشعارات الفوترة والإيصالات وتذكيرات التجديد.","الردّ على أسئلتك وتقديم دعم العملاء.","إرسال رسائل الخدمة بشأن التغييرات والأمان وحسابك.","تحسين الميّزات والموثوقية والأداء عبر تحليلات مجمّعة.","اكتشاف الاحتيال وإساءة الاستخدام ومشاكل الأمان ومنعها ومعالجتها.","الوفاء بالالتزامات القانونية والضريبية والتنظيمية."]},{p:"نحن **لا** نبيع معلوماتك الشخصية، ولا نستخدم بيانات العمل داخل مساحتك لتدريب نماذج ذكاء اصطناعي خارجية."}]},{title:"الأسس القانونية للمعالجة",blocks:[{p:"حيثما ينطبق، نعالج معلوماتك على الأسس التالية:"},{list:["**العقد** — لتقديم الخدمة التي اشتركت بها.","**المصالح المشروعة** — لتأمين الخدمة ودعمها وتحسينها.","**الموافقة** — للكوكيز الاختيارية والتسويق، ويمكنك سحبها.","**الالتزام القانوني** — للامتثال للقوانين الضريبية والمحاسبية وغيرها."]}]},{title:"كيف نشارك المعلومات",blocks:[{p:"نشارك المعلومات فقط في هذه الحالات المحدودة:"},{list:["**مزوّدو الخدمة** — جهات موثوقة تستضيف بنيتنا أو تعالج المدفوعات أو ترسل البريد نيابةً عنّا، بموجب عقود تُلزمها بحماية بياناتك.","**المتطلّبات القانونية** — عند الاقتضاء بموجب القانون أو اللوائح أو إجراء قانوني صحيح.","**انتقال الأعمال** — إذا شارك مدير أو إس في اندماج أو استحواذ أو بيع أصول، مع إشعارك بذلك.","**بتوجيه منك** — عندما تطلب ربط أداة خارجية أو مشاركة بيانات مع جهة ما."]}]},{title:"الاحتفاظ بالبيانات",blocks:[{p:"نحتفظ بمعلوماتك ما دام حسابك نشطاً. وإذا أغلقت حسابك أو انتهت تجربتك دون اشتراك، نحتفظ ببياناتك لفترة محدودة لتتمكّن من إعادة التفعيل، ثم نحذفها أو نجعلها مجهولة الهوية، إلا حيث يجب علينا الاحتفاظ بسجلّات للوفاء بالتزامات قانونية أو ضريبية أو محاسبية. ويمكنك طلب الحذف المبكّر في أي وقت."}]},{title:"الأمان",blocks:[{p:"نحمي بياناتك بالتشفير أثناء النقل والتخزين، وبضوابط الوصول والمراقبة المستمرّة. راجع {security} للتفاصيل. لا يوجد نظام آمن تماماً، لكننا نبذل جهدنا لحماية بيانات عملك ولإشعارك فوراً إذا أثّر أي خرق عليك."}]},{title:"حقوقك وخياراتك",blocks:[{list:["الاطّلاع على المعلومات الشخصية التي نحتفظ بها عنك.","تصحيح المعلومات غير الدقيقة أو الناقصة.","طلب حذف معلوماتك الشخصية.","تصدير بيانات عملك بصيغة قابلة للنقل.","الاعتراض على معالجة معيّنة أو تقييدها.","سحب الموافقة على الكوكيز الاختيارية أو التسويق في أي وقت."]},{p:"لممارسة أيّ من ذلك، راسلنا على {email}. نردّ خلال مدّة معقولة، وقد نحتاج إلى التحقّق من هويتك أولاً."}]},{title:"النقل الدولي",blocks:[{p:"قد تُعالَج بياناتك على خوادم خارج المملكة العربية السعودية. وعند نقل البيانات عبر الحدود، نستخدم ضمانات مناسبة لتبقى محمية بالمستوى الموصوف في هذه السياسة."}]},{title:"الأطفال",blocks:[{p:"مدير أو إس أداة أعمال وليس موجّهاً لمن هم دون الثامنة عشرة. ولا نجمع عن قصد معلومات من الأطفال."}]},{title:"تغييرات على هذه السياسة",blocks:[{p:"قد نحدّث هذه السياسة مع تطوّر المنتج والقانون. وعند إجراء تغييرات جوهرية، سنحدّث التاريخ أعلاه، ونشعرك عند الاقتضاء عبر البريد أو داخل المنتج."}]},{title:"تواصل معنا",blocks:[{p:"أسئلة حول الخصوصية؟ راسلنا على {email} أو تواصل معنا عبر {contact}."}]}]},refund:{eyebrow:"قانوني",title:"سياسة الاسترداد",intro:"نريد أن يكون قرار اختيار مدير أو إس سهلاً. وإليك بالضبط كيف تعمل التجارب والفوترة والاسترداد — دون مفاجآت.",updated:!0,clauses:[{title:"جرّب قبل أن تدفع",blocks:[{p:"تبدأ كل باقة بـ**تجربة مجانية ٣٠ يوماً**، دون الحاجة إلى بطاقة ائتمان. صُمّمت التجربة لتقيّم مدير أو إس بالكامل قبل أن تنفق أي شيء. ولذلك نادراً ما تُطرح أسئلة «استرداد الأموال» — فأنت لا تدفع إلا بعد أن تقرّر أن الخدمة مناسبة لك."}]},{title:"الاشتراكات الشهرية",blocks:[{list:["تُدفع الباقات المدفوعة شهرياً مقدّماً.","يتجدّد اشتراكك تلقائياً كل شهر حتى تلغيه.","نرسل إيصالاً بالبريد لكل عملية دفع."]}]},{title:"الإلغاء",blocks:[{p:"يمكنك الإلغاء في أي وقت من إعدادات حسابك. وعند الإلغاء:"},{list:["تبقى باقتك نشطة حتى نهاية دورة الفوترة الحالية.","لا تُحصَّل منك رسوم مرة أخرى بعد انتهاء تلك الدورة.","تحتفظ بإمكانية تصدير بياناتك قبل انتهاء وصولك."]},{p:"ولأن الوصول يستمرّ حتى نهاية الدورة التي دفعت ثمنها بالفعل، لا نقدّم استرداداً جزئياً عن الأيام غير المستخدمة من الدورة الشهرية."}]},{title:"متى نُصدر استرداداً",blocks:[{p:"سنسترد أي دفعة في حالات مثل:"},{list:["**رسوم مكرّرة أو غير مقصودة** — كأن تُحصَّل منك رسوم مرتين عن الفترة نفسها.","**أخطاء فوترة من جانبنا** — إذا حصّلنا مبلغاً خاطئاً، نصحّحه.","**رسوم مباشرة بعد تجربتك لم تقصدها** — إذا تواصلت معنا فوراً، سنتعامل معك بحسن نيّة.","**عطل ممتدّ في الخدمة** — إذا منعتك مشكلة من جانبنا من استخدام الخدمة لفترة طويلة ولم نتمكّن من حلّها."]}]},{title:"كيف تطلب استرداداً",blocks:[{p:"راسلنا على {email} من العنوان المسجّل في حسابك، أو راسلنا على {whatsapp}. أرفق بريد حسابك وملاحظة قصيرة عمّا حدث. نراجع كل طلب على حدة ونهدف إلى الردّ خلال أيام عمل قليلة."}]},{title:"كيف تُدفع المبالغ المستردّة",blocks:[{p:"تُعاد المبالغ المستردّة المعتمدة إلى وسيلة الدفع الأصلية. ويعتمد وقت ظهورها على بنكك أو مزوّد بطاقتك، وعادةً ما يكون بضعة أيام عمل بعد معالجتنا لها."}]},{title:"الضرائب",blocks:[{p:"حيثما ينطبق الاسترداد على دفعة شملت ضريبة القيمة المضافة أو ضرائب أخرى، يعكس المبلغ المستردّ الضريبة التي حُصّلت أصلاً، وفقاً للوائح المعمول بها."}]},{title:"أسئلة",blocks:[{p:"إذا كان أي شيء في الفوترة غير واضح، اسألنا قبل أن تُحصَّل منك الرسوم. راسلنا على {email} — نفضّل الإجابة عن سؤال مبكراً على معالجة رسوم لاحقاً."}]}]},terms:{eyebrow:"قانوني",title:"شروط الخدمة",intro:"تحكم هذه الشروط استخدامك لمدير أو إس. وبطلبك تجربة أو استخدامك الخدمة، فإنك توافق عليها.",updated:!0,clauses:[{title:"الموافقة على الشروط",blocks:[{p:"تشكّل شروط الخدمة هذه («الشروط») اتفاقاً مُلزِماً بينك وبين مدير أو إس بشأن استخدامك لمدير أو إس («الخدمة»). وإذا كنت تستخدم الخدمة نيابةً عن شركة، فإنك تؤكّد أنك مخوّل بقبول هذه الشروط عن تلك الشركة."}]},{title:"الخدمة",blocks:[{p:"مدير أو إس هو مدير الأعمال الذكي للشركات الصغيرة والمتوسطة في السعودية والخليج. يجمع المبيعات والمخزون والتدفّق النقدي والعملاء والتقارير في مساحة عمل واحدة، مع مساعد ذكي يُبرز ما يحتاج انتباهك. وقد نضيف ميّزات أو نغيّرها أو نزيلها بمرور الوقت لتحسين الخدمة."}]},{title:"التجربة المجانية",blocks:[{list:["تستمرّ التجربة المجانية **٣٠ يوماً** من التفعيل.","لا حاجة إلى بطاقة ائتمان لبدء التجربة.","يمكنك استخدام ميّزات التجربة لتقييم مدى ملاءمة الخدمة لعملك.","في نهاية التجربة، يمكنك اختيار باقة مدفوعة للمتابعة، أو ترك التجربة تنتهي دون رسوم.","قد نعدّل مدّة التجربة أو توافرها للتسجيلات المستقبلية، لكن ذلك لن يقصّر تجربة جارية بالفعل."]}]},{title:"الاشتراكات والفوترة",blocks:[{list:["تُدفع الباقات المدفوعة **شهرياً** مقدّماً، بالعملة المعروضة عند الدفع.","تتجدّد الاشتراكات تلقائياً كل شهر حتى تلغيها.","تُعرض الأسعار في قسم الأسعار ولا تشمل الضرائب المطبّقة (مثل ضريبة القيمة المضافة)، التي تُضاف عند الاقتضاء.","أنت مسؤول عن إبقاء بيانات الفوترة دقيقة ومحدّثة.","إذا فشلت عملية دفع، قد نعيد المحاولة وقد نعلّق الوصول حتى تُسدّد المستحقّات."]}]},{title:"الإلغاء والاسترداد",blocks:[{p:"يمكنك إلغاء اشتراكك في أي وقت من إعدادات حسابك؛ ويستمرّ الوصول حتى نهاية دورة الفوترة الحالية. ويخضع الاسترداد لـ{refund}."}]},{title:"مسؤولياتك",blocks:[{list:["حافظ على سرّية بيانات دخولك وأمانها.","احرص على التزام كل من تدعوهم إلى مساحتك بهذه الشروط.","قدّم معلومات حساب وفوترة دقيقة.","استخدم الخدمة بما يتوافق مع كل القوانين المطبّقة على عملك.","امتلك حقّ استخدام أي بيانات ترفعها إلى الخدمة أو احصل عليه."]}]},{title:"الاستخدام المقبول",blocks:[{p:"توافق على ألّا:"},{list:["تخالف القانون أو تنتهك حقوق الآخرين أثناء استخدام الخدمة.","تحاول الوصول إلى حسابات أو بيانات أو أنظمة ليست لك.","تفحص الخدمة أو تختبر ثغراتها دون إذن.","تُدخِل برمجيات خبيثة، أو تعطّل بنيتنا أو تُثقلها.","تعيد بيع الخدمة أو ترخيصها من الباطن أو تنسخها إلا كما تسمح هذه الشروط.","تعيد هندسة الخدمة إلا حيث يسمح القانون بذلك صراحةً."]}]},{title:"بياناتك وملكيّتها",blocks:[{p:"أنت تملك بيانات العمل التي تُدخلها في مدير أو إس. وتمنحنا الحقوق المحدودة اللازمة لاستضافتها ومعالجتها ونسخها احتياطياً وعرضها لتقديم الخدمة. ويمكنك تصدير بياناتك في أي وقت، ونتعامل معها كما هو موصوف في {privacy}."}]},{title:"الملكية الفكرية",blocks:[{p:"الخدمة، بما فيها برمجياتها وتصميمها وعلامتها التجارية، ملك لمدير أو إس ومحمية بقوانين الملكية الفكرية. وتمنحك هذه الشروط حقّاً محدوداً وغير حصري وغير قابل للنقل لاستخدام الخدمة؛ ولا تنقل ملكيّتها إليك."}]},{title:"التوافر والدعم",blocks:[{p:"نعمل على إبقاء الخدمة متاحة وموثوقة، لكننا لا نضمن وصولاً دون انقطاع. وقد نجري صيانة، وقد نحتاج إلى تعليق الخدمة أحياناً. والدعم متاح عبر البريد وواتساب؛ وتختلف أوقات الاستجابة حسب الباقة."}]},{title:"خدمات الأطراف الأخرى",blocks:[{p:"قد تتكامل الخدمة مع أدوات خارجية تختار ربطها. وتخضع تلك الأدوات لشروطها الخاصة، ولسنا مسؤولين عنها."}]},{title:"إخلاء المسؤولية",blocks:[{p:"تُقدَّم الخدمة «كما هي» و«حسب توافرها». وبالقدر الذي يسمح به القانون، نخلي مسؤوليتنا من ضمانات لم ننصّ عليها هنا صراحةً. يساعدك مدير أو إس على إدارة عملك، لكنك تبقى مسؤولاً عن قراراتك التجارية."}]},{title:"تحديد المسؤولية",blocks:[{p:"إلى أقصى حدّ يسمح به القانون، لن يكون مدير أو إس مسؤولاً عن الأضرار غير المباشرة أو العرضية أو التبعية، أو عن الأرباح أو البيانات المفقودة. وتقتصر مسؤوليتنا الإجمالية عن أي مطالبة تتعلّق بالخدمة على المبلغ الذي دفعته لنا في الاثني عشر شهراً السابقة لنشوء المطالبة."}]},{title:"الإنهاء",blocks:[{p:"يمكنك التوقّف عن استخدام الخدمة والإلغاء في أي وقت. وقد نعلّق الوصول أو ننهيه إذا خالفت هذه الشروط أو استخدمت الخدمة بطريقة تهدّد بإيذاء الآخرين أو أنظمتنا. وعند الإنهاء، ينتهي حقّك في استخدام الخدمة، ونتعامل مع بياناتك كما هو موصوف في {privacy}."}]},{title:"القانون الحاكم",blocks:[{p:"تخضع هذه الشروط لقوانين المملكة العربية السعودية. وتُنظر النزاعات أمام المحاكم المختصّة في المملكة العربية السعودية، ما لم يقتضِ القانون خلاف ذلك."}]},{title:"تغييرات على هذه الشروط",blocks:[{p:"قد نحدّث هذه الشروط مع تطوّر الخدمة. وعند التغييرات الجوهرية، سنحدّث التاريخ أعلاه ونشعرك عبر البريد أو داخل المنتج. ويعني استمرارك في استخدام الخدمة بعد سريان التغييرات قبولك للشروط المحدّثة."}]},{title:"تواصل",blocks:[{p:"أسئلة حول هذه الشروط؟ راسلنا على {email} أو زُر {contact}."}]}]}};function C({pageKey:e,route:i}){const{locale:s,t:o}=y(),r=d.useMemo(()=>{const a=S[e];return s==="ar"&&a?a:v[e]},[s,e]);return g(o.legalLinks),t.jsx(h,{route:i,eyebrow:r.eyebrow,title:r.title,intro:r.intro,updated:r.updated,children:t.jsx(k,{page:r})})}export{C as L};
